<?php
namespace App\Http\Controllers;
use App\Models\SuratMasuk;
use Illuminate\Http\Request;
class SuratMasukController extends Controller { public function index(Request $r){$q=$r->string('q');$data=SuratMasuk::when($q,fn($x)=>$x->where('nomor','like',"%$q%")->orWhere('asal','like',"%$q%")->orWhere('perihal','like',"%$q%"))->latest('tanggal')->paginate(15)->withQueryString();return view('surat-masuk.index',compact('data','q'));} public function create(){return view('surat-masuk.form',['item'=>new SuratMasuk]);} public function store(Request $r){$d=$r->validate(['nomor'=>'required','tanggal'=>'required|date','asal'=>'required','perihal'=>'required','disposisi'=>'nullable','status'=>'required']);SuratMasuk::create($d);return redirect()->route('surat-masuk.index')->with('success','Surat masuk berhasil disimpan.');} public function edit(SuratMasuk $suratMasuk){return view('surat-masuk.form',['item'=>$suratMasuk]);} public function update(Request $r,SuratMasuk $suratMasuk){$d=$r->validate(['nomor'=>'required','tanggal'=>'required|date','asal'=>'required','perihal'=>'required','disposisi'=>'nullable','status'=>'required']);$suratMasuk->update($d);return redirect()->route('surat-masuk.index')->with('success','Surat masuk diperbarui.');} public function destroy(SuratMasuk $suratMasuk){$suratMasuk->delete();return back()->with('success','Surat masuk dihapus.');} }
